mapper.select:
SELECT R.RQST_NO, R.RQST_LOGIN_ID, R.RQST_MNGR_NM, R.RQST_DUTY_CD, R.RQST_DT, R.APRV_DT, R.RQST_STTS_CD AS RQST_STTS_CD, R.APRV_ID, R.RJCT_RSN_CN, R.RMRK_CN, R.USER_NO,
/* 신청 단건 조회는 승인 처리용이다.
→ 승인 처리에는 RQST_NO, USER_NO, RQST_STTS_CD만 있으면 된다. → 모든 ROLE_MNGR이 입주민은 아니므로 RESIDENT_RQST와 연결하면 업무 흐름이 꼬일 수 있다. */
CASE R.RQST_DUTY_CD WHEN 'DUTY_HEAD' THEN '관리소장' WHEN 'DUTY_ACC' THEN '회계' WHEN 'DUTY_ADMIN' THEN '행정' WHEN 'DUTY_FAC' THEN '시설' WHEN 'HEAD' THEN '관리소장' WHEN 'ACNT' THEN '회계' WHEN 'ADM' THEN '행정' WHEN 'FAC' THEN '시설' ELSE R.RQST_DUTY_CD END AS DUTY_NM,
CASE R.RQST_STTS_CD WHEN 'WAIT' THEN '승인대기' WHEN 'OK' THEN '승인완료' WHEN 'RJCT' THEN '반려' WHEN 'CNL' THEN '신청취소' ELSE R.RQST_STTS_CD END AS STTS_NM
FROM MNGR_RQST R WHERE R.RQST_NO = #{rqstNo}

SELECT COUNT(*)
FROM MEMBER
WHERE USER_ID = #{userId}

mapper.update:
UPDATE AUTH
SET USER_ROLE_CD = 'ROLE_MNGR'
WHERE USER_NO = #{userNo}

mapper.select:
SELECT COUNT(*)
FROM MANAGER
WHERE USER_NO = #{userNo}

mapper.update:
UPDATE MNGR_RQST
SET ACNT_DSPLY_YN = 'N'
WHERE RQST_NO = #{rqstNo}
